 private static function update(mysqli$d,string$p,array$c,string$o,string$a):void{$s=$d->prepare("UPDATE `{$p}fm2_workforce_catalog` SET position=?,employment_status=?,workforce_source='one_c_zup_via_bitrix_reconciled',workforce_source_updated_at=?,delivery_system='bitrix24',delivery_person_id=?,dismissal_time_quality='observed_only',reconciliation_state='delivered',authority_system='one_c_zup',last_successful_sync_run_id=?,last_successful_sync_at=? WHERE installer_tab_id=? AND (authority_system IS NULL OR authority_system='') AND reconciliation_state='missing_from_delivery'");$s->bind_param('sssissi',$c['position'],$c['status'],$a,$c['personId'],$o,$a,$c['tab']);$s->execute();if($s->affected_rows!==1)throw new DomainException('WORKFORCE_RECONCILIATION_CONFLICT');}
